package kr.chacademy.story;
import kr.chacademy.story.dialogue.*;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
class JournalLedgerTest {
 @TempDir Path dir;
 @Test void editsPreserveLifetimeRewardAndAffinityGuardsAcrossReload()throws Exception{Path p=dir.resolve("ledger.properties");var s=new LocalDialogueStore(p);assertTrue(s.claimEvent("ch1","once"));assertTrue(s.complete("ch1"));s.journalEdit("ch1","reset");s.journalEdit("ch1","grant");s.journalEdit("ch1","progress");s.journalEdit("ch1","complete");var reloaded=new LocalDialogueStore(p);assertTrue(reloaded.done("ch1"));assertFalse(reloaded.claimEvent("ch1","once"));assertFalse(reloaded.complete("ch1"));assertEquals("claimed",reloaded.journalState("ch1"));}
 @Test void displayCompleteDoesNotCreateRewardOrAffinityEvents()throws Exception{var s=new LocalDialogueStore(dir.resolve("ledger.properties"));s.journalEdit("ch1","complete");assertFalse(s.done("ch1"));assertFalse(s.hasAffinity("ch1","scene.a"));s.journalEdit("ch1","reset");assertEquals("hidden",s.journalState("ch1"));assertTrue(s.journalIds().contains("ch1"));}
 @Test void metadataSurvivesWithoutContentAndInvalidEditCannotWrite()throws Exception{Path p=dir.resolve("ledger.properties");var s=new LocalDialogueStore(p);var d=new Dialogue("ch1","User title","start",Map.of(),Map.of(),DialogueCommands.EMPTY,"User description");s.journalSeen(d);var reloaded=new LocalDialogueStore(p);assertEquals("User title",reloaded.journalTitle("ch1"));assertEquals("User description",reloaded.journalDescription("ch1"));assertEquals("active",reloaded.journalState("ch1"));assertThrows(java.io.IOException.class,()->reloaded.journalEdit("ch1","reward"));assertThrows(java.io.IOException.class,()->reloaded.journalEdit("../x","reset"));}
 @Test void activeRunnerPreservesLaterEditsFromAnotherStoreInstance()throws Exception{Path p=dir.resolve("shared.properties");var runner=new LocalDialogueStore(p);var admin=new LocalDialogueStore(p);admin.journalEdit("other","grant");runner.claimEvent("ch1","once");assertEquals("active",new LocalDialogueStore(p).journalState("other"));admin.journalEdit("other","complete");assertFalse(runner.claimEvent("ch1","once"));runner.complete("ch1");var actual=new LocalDialogueStore(p);assertEquals("claimed",actual.journalState("other"));assertTrue(actual.done("ch1"));}
}
